package io.earthplatform.minecraft.lod;
import io.earthplatform.core.*;
import io.earthplatform.minecraft.enginebridge.*;
import io.earthplatform.minecraft.scene.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.joml.Matrix4f;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.earthplatform.minecraft.lod.DhArenaTestFixtures.*;
@Timeout(40)
class DhPreparedArenaTest {
 static final CubePos HOME=new CubePos(0,9,0),AWAY=new CubePos(-4,9,-4);
 static final class Harness implements AutoCloseable {
  final DhPreparedReplacementTest.Driver driver=new DhPreparedReplacementTest.Driver();final ExecutorService executor=Executors.newSingleThreadExecutor();final AtomicReference<String> identity=new AtomicReference<>(SOURCE.identity());final DhPreparedLodView view;
  Harness(){var sampler=new DhArenaSurfaceSampler(SOURCE);view=new DhPreparedLodView(new SceneSurfaceSampler(){public long surfaceY(long x,long z){return sampler.surfaceY(x,z);}public int argb(long x,long z,long y){return sampler.argb(x,z,y);}public String identity(){return identity.get();}public boolean supportsConcurrentReads(){return true;}public boolean supportsFootprintCoverage(){return true;}public boolean knownFootprint(long x,long z,long xx,long zz){return sampler.knownFootprint(x,z,xx,zz);}},WORLD,EPOCH,RESOURCE,0,0,DhLodLayout.ARENA_4096,driver,executor);view.initialize();}
  DhPreparedLodView.CoverageTicket prepare(long gen,CubePos c,DhArenaInput in){var t=view.prepareCoverageArena(gen,ready(c),center(c.x()),center(c.z()),in);DhPreparedReplacementTest.until(()->view.isPrepared(t),view::pump);return t;}
  void commit(long gen,CubePos c,DhArenaInput in){assertTrue(view.commitPrepared(prepare(gen,c,in)));}
  long n(String k){return view.diagnostics().get(k).getAsLong();}
  public void close(){try{view.close();assertEquals(0,n("residentPageTileOwners"));}finally{executor.shutdownNow();}}
 }
 @Test void cleanZeroAuthorityRemainsExactWhenWholeArenaRetiresAndReturns(){try(var h=new Harness()){var in=input(new Guard(),1,0);h.commit(1,HOME,in);assertTrue(h.view.arenaReady(in.certificateIdentity()));assertFalse(h.view.replacementReady(null));h.commit(2,AWAY,in);assertTrue(h.n("replacementVisibleFaces")>0);assertTrue(h.n("residentPageTileOwners")<=128);assertTrue(h.n("pageTileOwners")<=64);assertEquals(11664,h.view.diagnostics().getAsJsonObject("arena").get("captureBytes").getAsLong());h.commit(3,HOME,in);assertTrue(h.view.arenaReady(in.certificateIdentity()));}}
 @Test void pendingCompleteAuthorityCannotReplacePublishedUntilExactAllow(){try(var h=new Harness()){var a=input(new Guard(),1,0);h.commit(1,HOME,a);var b=input(new Guard(),2,1,capture().withMaterial(15,144,15,0));var t=h.prepare(2,HOME,b);assertTrue(h.view.arenaReady(a.certificateIdentity()));assertFalse(h.view.arenaReady(b.certificateIdentity()));assertTrue(h.view.commitPrepared(t));assertFalse(h.view.commitPrepared(t));assertTrue(h.view.arenaReady(b.certificateIdentity()));assertFalse(h.view.arenaReady(a.certificateIdentity()));assertEquals(0,h.n("sameGeometryCommits"));}}
 @Test void unchangedAuthorityReusesGeometryOnlyWithFreshTicket(){try(var h=new Harness()){var a=input(new Guard(),1,0);h.commit(1,AWAY,a);int uploads=h.driver.uploads;var t=h.prepare(2,AWAY,a);assertTrue(h.view.coverageReady(1));assertTrue(h.view.commitPrepared(t));assertEquals(uploads,h.driver.uploads);assertEquals(1,h.n("sameGeometryCommits"));}}
 @Test void currentAndHistoricalRevocationAreIndependentStickyAndCommitRevokesOldToken(){try(var h=new Harness()){var g=new Guard();var a=input(g,1,0);h.commit(1,AWAY,a);var old=h.view.retainPresentation();g.current=false;assertFalse(h.view.arenaReady(a.certificateIdentity()));g.current=true;assertFalse(h.view.arenaReady(a.certificateIdentity()));assertTrue(h.view.drawPresented(old,new Matrix4f(),0,145,0,RESOURCE));g.historical=false;assertFalse(h.view.isPresentationCurrent(old));g.historical=true;assertFalse(h.view.isPresentationCurrent(old));h.commit(2,AWAY,input(new Guard(),2,1));assertFalse(h.view.isPresentationCurrent(old));}}
 @Test void noLegacyNoneOrSetDowngradeCanDropRetiredArena(){try(var h=new Harness()){var a=input(new Guard(),1,0);h.commit(1,AWAY,a);assertThrows(IllegalStateException.class,()->h.view.prepareCoverage(2,ready(HOME),0,0,null));assertTrue(h.view.arenaReady(a.certificateIdentity()));assertEquals(1,h.n("highestRequestedCoverageGeneration"));}}
 @Test void sourceEpochResourceMismatchRejectsAndNeverResurrects(){try(var h=new Harness()){var c=capture();var a=input(new Guard(),1,0,c);h.commit(1,AWAY,a);for(boolean epoch:new boolean[]{true,false}){var bad=new DhArenaInput(SOURCE,certificate(c,2,0,EPOCH+(epoch?1:0),RESOURCE+(epoch?0:1),"c".repeat(64),"d".repeat(64),0),c,new Guard());assertThrows(IllegalStateException.class,()->h.view.prepareCoverageArena(2,ready(HOME),0,0,bad));assertTrue(h.view.arenaReady(a.certificateIdentity()));}var old=h.view.retainPresentation();assertFalse(h.view.drawPresented(old,new Matrix4f(),0,145,0,RESOURCE+1));h.identity.set("changed");assertThrows(IllegalStateException.class,()->h.view.isPresentationCurrent(old));h.identity.set(SOURCE.identity());assertFalse(h.view.isPresentationCurrent(old));}}
 @Test void revokedCandidateCannotConsumeAllow(){try(var h=new Harness()){var a=input(new Guard(),1,0);h.commit(1,HOME,a);var g=new Guard();var b=input(g,2,1);var t=h.prepare(2,AWAY,b);g.current=false;assertFalse(h.view.isPrepared(t));assertFalse(h.view.commitPrepared(t));h.view.pump();assertTrue(h.view.arenaReady(a.certificateIdentity()));}}
 @Test void compilerIgnoringCancellationCannotPublishObsoleteArena()throws Exception{try(var h=new Harness()){var a=input(new Guard(),1,0);h.commit(1,HOME,a);var gates=new CountDownLatch[]{new CountDownLatch(1),new CountDownLatch(1)};h.driver.block.set(gates);var t=h.view.prepareCoverageArena(2,ready(AWAY),center(AWAY.x()),center(AWAY.z()),input(new Guard(),2,1));assertTrue(gates[0].await(10,TimeUnit.SECONDS));h.view.cancelPrepared(t);gates[1].countDown();h.commit(3,HOME,a);assertFalse(h.view.commitPrepared(t));assertTrue(h.view.arenaReady(a.certificateIdentity()));}}
 @Test void uploadFaultFencesRatherThanExposingReadonlyBase(){try(var h=new Harness()){h.commit(1,HOME,input(new Guard(),1,0));h.driver.failUpload=true;var t=h.view.prepareCoverageArena(2,ready(AWAY),center(AWAY.x()),center(AWAY.z()),input(new Guard(),2,1));assertThrows(IllegalStateException.class,()->DhPreparedReplacementTest.until(()->h.view.isPrepared(t),h.view::pump));assertFalse(h.view.isReplacementDeclined(t));assertTrue(h.view.diagnostics().get("invalidated").getAsBoolean());}}
 @Test void cleanupFailureRetainsOwnedMeshesUntilExactRetry(){var h=new Harness();try{h.commit(1,AWAY,input(new Guard(),1,0));h.driver.all.forEach(m->m.failClose=true);assertThrows(IllegalStateException.class,h.view::close);assertTrue(h.n("residentPageTileOwners")>0);h.driver.all.forEach(m->m.failClose=false);h.view.close();assertEquals(0,h.n("residentPageTileOwners"));}finally{h.driver.all.forEach(m->m.failClose=false);h.close();}}
 @Test void queryRootIndexLeasesAndCaptureBindTheCompleteCachedIdentity(){var cap=capture();var a=input(new Guard(),1,0,cap);for(int variant=0;variant<3;variant++){var c=certificate(cap,1,0,EPOCH,RESOURCE,variant==0?"b".repeat(64):"c".repeat(64),variant==1?"e".repeat(64):"d".repeat(64),variant==2?100:0);assertNotEquals(a.identity(),new DhArenaInput(SOURCE,c,cap,new Guard()).identity());}assertSame(a.certificateIdentity(),a.data().certificateIdentity());assertThrows(IllegalArgumentException.class,()->new DhArenaInput(SOURCE,a.certificate(),cap.withMaterial(15,144,15,2),new Guard()));for(var f:DhArenaInput.Data.class.getDeclaredFields()){assertNotEquals(DhArenaInput.class,f.getType());assertFalse(DhArenaInput.AuthorityGuard.class.isAssignableFrom(f.getType()));}}
 @Test void reentrantGuardInvalidationCannotReturnReadyOrDraw(){try(var h=new Harness()){var g=new Guard();var a=input(g,1,0);h.commit(1,HOME,a);g.callback=h.view::requestInvalidation;assertFalse(h.view.arenaReady(a.certificateIdentity()));h.view.draw(new Matrix4f(),0,145,0,RESOURCE);assertEquals(0,h.driver.draws);}}
}
